//! The shard's view of the ABI. Every guest-ring and IPC value comes from the
//! jitk-abi crate (../abi); only host-local KVM details are defined here.
pub mod ring {
    pub use jitk_abi::ring::*;
    /// KVM memslot of the read-only archive extent at `ARCHIVE_GPA`.
    pub const INPUT_SLOT: u32 = 63;
}
pub use jitk_abi::{ABI_VERSION, ipc};
pub mod kvm {
    // Checked in, generated by ../abi-gen.ts; tests/kvm_abi.rs checks it
    // against the host UAPI headers. Plain numbers, so the seccomp policy
    // (confine::policy) is tested on any host.
    include!("kvm_abi.rs");
}
